# Price (in cents) of a group of `n` different books, after the discount.
GROUP_PRICES = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    counts = sorted((basket.count(title) for title in range(1, 6)), reverse=True)

    total = 0
    while any(counts):
        size = sum(1 for count in counts if count > 0)
        total += GROUP_PRICES[size]
        for i in range(size):
            counts[i] -= 1
        counts.sort(reverse=True)

    return total
